} from './service';

describe('LoyaltyPointService (Ground Truth)', () => {
  let accountRepo: jest.Mocked<ILoyaltyAccountRepository>;
  let ledgerRepo: jest.Mocked<ILoyaltyLedgerRepository>;
  let fraudDetector: jest.Mocked<IFraudDetectionService>;
